#!/usr/bin/env python3
"""Render the GitHub Pages site (docs/*.html) and the derived knowledge docs from JSON only.

Inputs: docs/downloads/manifest.json, evidence/*.json, registry/*.json, docs/data/*. No rasters are needed, so this runs in CI.
Nothing here fetches drivendata.org or invents a score: scores come from registry/live_scores.json (owner-reported).
"""

from __future__ import annotations

import csv
import html
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from gems27.readiness import publication_decision  # noqa: E402

DOCS, EV, REG, KN = ROOT / "docs", ROOT / "evidence", ROOT / "registry", ROOT / "knowledge"
REPO_URL = "https://github.com/buffedlizard55-lab/GEMSDOE27"
DD_COMP = "https://www.drivendata.org/competitions/306/competition-doe-gems/"
DD_LB = DD_COMP + "leaderboard/"
NAV = [("index.html", "Submit status"), ("executive-summary.html", "Executive summary"), ("how-to-submit.html", "How to submit"),
       ("topology.html", "Topology candidates"), ("research.html", "Research"), ("sources.html", "Sources & feed")]


def J(p: Path):
    return json.loads(p.read_text())


def e(x) -> str:
    return html.escape(str(x), quote=True)


def h33_card() -> dict | None:
    path = EV / "h33_run_card_2026-10-27.json"
    if not path.is_file():
        return None
    try:
        return J(path)
    except (OSError, json.JSONDecodeError):
        return None


def h33_banner() -> str:
    """First-screen verdict for the unique TIFF generated by lane H33-1."""
    card = h33_card()
    if not card:
        return (
            "<div class=\"stopbox\"><h2>No H33 TIFF yet</h2>"
            "<p>The 2026-10-27 lane has not written a run card. Do not upload an older file from this page.</p></div>"
        )
    raster = card.get("raster") or {}
    name = raster.get("primary_allfinite") or ""
    rel = f"downloads/research/{name}" if name else ""
    note = card.get("note_max_140_chars") or ""
    hold = card.get("holdout") or {}
    decision = card.get("download_decision") or "DO NOT SUBMIT"
    verdict = card.get("verdict") or "negative"
    dti = hold.get("pooled_candidate")
    dti_txt = f"{dti:.4f}" if isinstance(dti, (int, float)) else "not scored"
    ci = (hold.get("paired_candidate_minus_B") or {}).get("ci95") or hold.get("ci95") or []
    ci_txt = f"[{ci[0]:+.4f}, {ci[1]:+.4f}]" if isinstance(ci, list) and len(ci) == 2 else "n/a"
    n_pos = hold.get("n_withheld_positives_total", "n/a")
    sha = (raster.get("sha256") or "")[:16]
    dots = raster.get("dots", "n/a")
    promote = verdict == "promote" and card.get("ok_to_submit") is True and card.get("slot_authorized") is True
    box = "okbox" if promote else "stopbox"
    headline = "OK TO DOWNLOAD AND SUBMIT" if promote else "NOT OK TO SUBMIT"
    link = (
        f"<p><a class=\"btn\" href=\"{e(rel)}\" download>Download {e(name)}</a></p>"
        if name and promote else
        (f"<p><a class=\"btn alt\" href=\"{e(rel)}\" download>Download research TIFF — do not submit</a> "
         f"<span class=\"small\">{e(name)}</span></p>" if name else "<p>No TIFF was placed.</p>")
    )
    return f"""
<div class="{box}" id="h33-verdict">
<h2>{headline}</h2>
<p><b>Generated unique file:</b> <code>{e(name) or "none"}</code>.
<b>Decision:</b> {e(decision)}</p>
<p>This is <b>HOLDOUT-DTI</b>, not a leaderboard score. Evaluator: {e(hold.get("evaluator", "n/a"))}.
Pooled candidate HOLDOUT-DTI <b>{e(dti_txt)}</b> on <b>{e(n_pos)}</b> withheld-positive occurrences
(seeds 520–529, whole-FID buffered hide-and-recover). Paired Δ vs base-32 control 95% CI {e(ci_txt)}.
Verdict <code>{e(verdict)}</code>. Weekly slot authorized: <b>no</b>.</p>
{link}
<p class="small">Note (≤140 characters, copy only if a selector later authorizes a slot): <code>{e(note)}</code></p>
<p class="small">sha256 prefix {e(sha) or "n/a"} · dots {e(dots)} · research path, not a historical resubmission.
Do not upload GEMSDOE32 <code>h33-h33-2-b2</code> or any other focus-site file from this page.</p>
</div>
"""


def layout(fname: str, title: str, body: str, stamp: str, approved_name: str | None = None) -> str:
    nav = "".join(f'<a href="{h}"{" class=on" if h == fname else ""}>{e(t)}</a>' for h, t in NAV)
    status_meta = (
        "2026-10-27 generated TIFF is NOT OK TO SUBMIT. "
        + (f"Historical {approved_name} is format-valid and not slot-authorized." if approved_name
           else "No current TIFF is approved for submission.")
    )
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{e(title)} · 27GEMSDOE</title><meta name="description" content="27GEMSDOE: geothermal &amp; structural fault discovery for DrivenData #306 (DOE GEMS). {e(status_meta)}">
<link rel="stylesheet" href="assets/style.css"></head><body>
<header class="top"><div class="in"><a class="brand" href="index.html">27GEMSDOE · DOE GEMS</a><nav>{nav}</nav></div></header>
<main><div class="card"><b>Automatic submission evidence audit (zero human intervention):</b>
<a href="data/submission_readiness_audit.json">Read byte-bound gate decisions and blockers</a> &middot;
<a href="how-to-submit.html">How to submit to DrivenData #306</a>.
<a href="../knowledge/28_submission_readiness_audit_2026-10-26.md">Latest executive audit and limitations</a>.<br>
<strong>NOT AUTHORIZED FOR A WEEKLY SLOT by this page:</strong> evidence PASS is not selector approval.
The 2026-10-27 unique TIFF verdict is the box at the top of Submit status and the executive summary.
Format PASS alone never authorizes a slot. Historical focus-site files are not unique resubmissions.
</div>{body}</main>
<footer>Built {e(stamp)} from <a href="{REPO_URL}">the repository</a>. {e(status_meta)} No unverified leaderboard score is claimed on this site; historical scores shown are explicitly labelled OWNER-REPORTED. This site never contacts drivendata.org.</footer>
<script src="assets/app.js"></script></body></html>"""


def rebase(text: str, prefix: str) -> str:
    """Prefix every relative href/src (used for the repository-root copy of the front page)."""
    import re
    return re.sub(r'(href|src)="(?!https?:|#|mailto:|data:)([^"]+)"', lambda m: f'{m.group(1)}="{prefix}{m.group(2)}"', text)


def kb(n: float, d=0) -> str:
    return f"{n:,.{d}f}"


def build() -> None:
    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    man = J(DOCS / "downloads" / "manifest.json")
    P, S, T = man["primary"], man["secondary"], man["tertiary"]
    # Keep historical peer artifacts auditable without presenting a raw GeoTIFF as a download.
    reference_audit_url = man["reference_0_2477"]["url"].replace("/raw/", "/blob/")
    Q = man.get("quaternary")
    Q5 = man["quinary_probe"]
    sgi = J(EV / "sgmc_gap_inversion.json") if (EV / "sgmc_gap_inversion.json").exists() else None
    hab = J(EV / "arm_habitat_decomposition.json") if (EV / "arm_habitat_decomposition.json").exists() else None
    addD = J(EV / "addendum_d_gates.json") if (EV / "addendum_d_gates.json").exists() else None
    gval = J(REG / "topology_candidates.json")["summary"].get("graph_value", {})
    # ---- Lane L-2026-10-25 parallel negative (JSON-driven; research/ per STOP policy) ----
